INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 1, 'AVOCAT*', 'Déontologie', 'Principes essentiels de la profession', 'Manquement', 'Caractérisation', 'Risque sérieux de conflit d''intérêt', 'Défaut d''avertissement des clients', NULL, NULL, NULL, NULL, NULL, NULL, 'Il se déduit de l''article 1240 du code civil, de l''article 7, alinéa 1, devenu l''article 7, alinéa 1, du décret n° 2023-552 du 30 juin 2023 portant code de déontologie des avocats, et de l''article 9 du décret n° 2005-790 du 12 juillet 2005 relatif aux règles de déontologie de la profession d''avocat que, si le seul fait pour un avocat rédacteur d''acte d''être le conseil des deux parties à cet acte ne le place pas nécessairement en situation de conflit d''intérêts, il doit, dès lors qu''il existe un risque sérieux d''un tel conflit, en avertir ses clients et obtenir leur accord pour poursuivre sa mission', NULL);
INSERT INTO ANALYSE (ID_DOCUMENT, NUM_ANALYSE, PM, AM1, AM2, AM3, AM4, AM5, AM6, AM7, AM8, AM9, AM10, AM11, AM12, SOMMAIRE, TITRE_REFERENCE) VALUES (${SOURCEID}, 2, 'AVOCAT*', 'Responsabilité', 'Faute', 'Caractérisation', 'Conseil de plusieurs clients entre lesquels il existe un conflit d''intérêt', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Il résulte de l''article 1240 du code civil et de l''article 7, alinéa 1, du décret n° 2005-790 du 12 juillet 2005 relatif aux règles de déontologie de la profession d''avocat,  devenu l''article 7, alinéa 1, du décret n° 2023-552 du 30 juin 2023 portant code de déontologie des avocats que constitue une faute le fait, pour un avocat, d''être le conseil de plusieurs clients lorsqu''il existe un conflit entre les intérêts de ces derniers, indépendamment de tout manquement à son devoir de conseil et qu''une telle faute suffit à engager la responsabilité de l''avocat lorsqu''elle cause un préjudice', NULL);